// =============================================================================
// Internal charPropsFor -- branchless clamp + 3-level lookup
// =============================================================================

uint32_t AttributedChar::charPropsFor (uint32_t cp) noexcept
{
    // Branchless clamp: if cp > maxUnicode, set to 0
    const int64_t  diff { static_cast<int64_t> (cp) - static_cast<int64_t> (maxUnicode + 1u) };
    const uint32_t mask { static_cast<uint32_t> (diff >> 63) };
    cp = cp & mask;

    return charPropsT3[charPropsT2[(static_cast<uint32_t> (charPropsT1[cp >> charPropsShift]) << charPropsShift)
                                   + (cp & charPropsMask)]];
}

// =============================================================================
// jam::AttributedChar static method bodies
// =============================================================================

int AttributedChar::width (uint32_t codepoint) noexcept
{
    const uint32_t props { charPropsFor (codepoint) };
    return static_cast<int> ((props >> AttributedChar::bitWidthShifted) & ((1u << AttributedChar::widthFieldBits) - 1u)) - AttributedChar::widthShift;
}

bool AttributedChar::isWordChar (uint32_t codepoint) noexcept
{
    const uint32_t props { charPropsFor (codepoint) };
    return static_cast<bool> ((props >> AttributedChar::bitIsWordChar) & ((1u << AttributedChar::boolFieldBits) - 1u));
}

bool AttributedChar::isCombining (uint32_t codepoint) noexcept
{
    const uint32_t props { charPropsFor (codepoint) };
    return static_cast<bool> ((props >> AttributedChar::bitIsCombining) & ((1u << AttributedChar::boolFieldBits) - 1u));
}

